 function publicCaptureResponse<T>(method:string,path:string,data:T,status:number):T{
  if(!path.startsWith(base+'/')||status>=400)return data;
  const contract=require('@study-agent/contracts'),route=path.slice(base.length+1).split('?')[0];
  if(route.startsWith('repair-commands/')){contract.paperCaptureRepairCommandLookupSchema.parse(data);return data;}
  if(route.startsWith('repair-uploads')){if(method==='post')contract.paperCaptureRepairCommandResultSchema.parse(data);else if(route==='repair-uploads')contract.paperCaptureRepairUploadViewSchema.array().parse(data);else contract.paperCaptureRepairUploadViewSchema.parse(data);return data;}
  if(route==='repairs'||route.startsWith('repairs/')){if(method==='post')contract.paperCaptureRepairCommandResultSchema.parse(data);else if(route==='repairs')contract.paperCaptureRepairViewSchema.array().parse(data);else contract.paperCaptureRepairViewSchema.parse(data);return data;}
  if(method==='post')contract.paperCaptureCommandResultSchema.parse(data);
  else if(/^uploads\/[^/]+\/commands$/.test(route))contract.paperCaptureUploadCommandsSchema.parse(data);
  else if(method==='put'||/^uploads\/[^/]+$/.test(route))contract.paperCaptureUploadViewSchema.parse(data);
  else if(route==='limits')contract.paperCaptureLimitsSchema.parse(data);
  else if(route.startsWith('commands/'))contract.paperCaptureCommandLookupSchema.parse(data);
  else if(/^(pages|derivations)\/[^/]+\/files$/.test(route))contract.paperCaptureFileReportSchema.parse(data);
  else if(route==='uploads')contract.paperCaptureUploadViewSchema.array().parse(data);
  else if(/^pages\/[^/]+$/.test(route))contract.paperCapturePageViewSchema.parse(data);
  else if(route==='groups')contract.paperCaptureGroupViewSchema.array().parse(data);
  else if(/^groups\/[^/]+$/.test(route))contract.paperCaptureGroupViewSchema.parse(data);
  else if(/^groups\/[^/]+\/derivations$/.test(route))contract.paperCaptureDerivationViewSchema.array().parse(data);
  else if(/^derivations\/[^/]+$/.test(route))contract.paperCaptureDerivationViewSchema.parse(data);
  return data;
 }
