 async function rejectsColdMutation(collection:string,id:string,mutate:(row:any)=>any){
  const location=process.env.STUDY_STORAGE==='postgres'?process.env.DATABASE_URL!:resolve(process.env.STUDY_DATA_DIR!,'study-agent.sqlite3');await app.close();let sql:DatabaseSync|undefined,pool:Pool|undefined;
  if(process.env.STUDY_STORAGE==='postgres'){const url=new URL(location);if(url.pathname!=='/study_agent_qa'||url.port!=='15439'||!/^\-c search_path=study_qa_paper_[a-f0-9]{32}$/.test(url.searchParams.get('options')??''))throw Error('Only the current generated paper QA schema may be mutated');pool=new Pool({connectionString:location});}else{if(!location.startsWith(qa+'/')&&!location.startsWith(qa+'\\'))throw Error('Only generated paper QA SQLite may be mutated');sql=new DatabaseSync(location);}
  const original=pool?(await pool.query('SELECT collection,record_id,body,position FROM domain_records WHERE collection=$1 AND record_id=$2',[collection,id])).rows[0]:sql!.prepare('SELECT collection,record_id,body,position FROM domain_records WHERE collection=? AND record_id=?').get(collection,id)as any;
  const write=async(body:any)=>{if(body===null){if(pool)await pool.query('DELETE FROM domain_records WHERE collection=$1 AND record_id=$2',[collection,id]);else sql!.prepare('DELETE FROM domain_records WHERE collection=? AND record_id=?').run(collection,id);}else{const bytes=JSON.stringify(body);if(pool)await pool.query('INSERT INTO domain_records VALUES($1,$2,$3::jsonb,$4) ON CONFLICT(collection,record_id) DO UPDATE SET body=excluded.body,position=excluded.position',[collection,id,bytes,original.position]);else sql!.prepare('INSERT INTO domain_records VALUES(?,?,?,?) ON CONFLICT(collection,record_id) DO UPDATE SET body=excluded.body,position=excluded.position').run(collection,id,bytes,original.position);}};
  const body=typeof original.body==='string'?JSON.parse(original.body):structuredClone(original.body);
  try{await write(mutate(structuredClone(body)));const reader=new(load('infrastructure/domain-database').DomainDatabase)(location);try{await expect(reader.open()).rejects.toThrow('paper_capture_saved_integrity_failed');}finally{await reader.close();}}finally{await write(body);sql?.close();await pool?.end();await boot();}
 }
